//! The books against rook_core's own vectors (tests/fixtures/solana/rook-core-vectors.json, generated by
//! solana/programs/rook_core/src/vectors.rs from rook_core's code), and the books' stable encoding.

mod books_common;

use books_common::*;
use etch_autobuyer::books::floor::MAX_ITEMS_PER_DAY;
use etch_autobuyer::books::math::{is_taproot_on, keccak, leaf_of, verify_proof, LAMPORTS_PER_SOL};
use etch_autobuyer::books::*;
use serde_json::{json, Value};

fn fixture() -> Value {
    let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/solana/rook-core-vectors.json");
    serde_json::from_str(&std::fs::read_to_string(p).expect("the vectors")).expect("json")
}

// As tests/solana.rs `the_ported_floor_rules_and_hashing_match_rook_cores_own_vectors`, against the books' port: freshness, the
// floor bounds, the item cap, `max_item_cost`, `net_units`, `arrival_room`; and the hashing and taproot rules.
#[test]
fn the_books_floor_rules_and_hashing_match_rook_cores_own_vectors() {
    let v = fixture();
    let n = |c: &Value, k: &str| c[k].as_u64().unwrap_or_else(|| panic!("{k}"));
    let i = |c: &Value, k: &str| c[k].as_i64().unwrap_or_else(|| panic!("{k}"));
    let cases = v["floor"].as_array().unwrap();
    assert_eq!(cases.len(), 400);
    let mut nontrivial = 0;
    for (k, c) in cases.iter().enumerate() {
        let mut p = etch_autobuyer::books::default_params(20 * LAMPORTS_PER_SOL);
        p.max_move_bps = n(c, "max_move_bps") as u16;
        p.conv_bps = n(c, "conv_bps") as u16;
        p.max_items_per_day = n(c, "max_items_per_day") as u16;
        p.min_confidence_bps = n(c, "min_confidence_bps") as u16;
        p.buffer_bps = n(c, "buffer_bps") as u16;
        let mut m = Module::new(p).unwrap();
        m.accepted = n(c, "accepted");
        m.posted_at = i(c, "posted_at");
        m.confidence_bps = n(c, "confidence_bps") as u16;
        m.day_anchor = n(c, "day_anchor");
        m.day_anchor_at = i(c, "day_anchor_at");
        m.backing = n(c, "backing");
        m.revenue = n(c, "revenue");
        m.surplus = n(c, "surplus");
        m.transit_units = n(c, "transit_units");
        m.reserve_units = n(c, "reserve_units");
        m.snap_cap = n(c, "snap_cap");
        m.snap_at = i(c, "snap_at");
        m.arrivals = n(c, "arrivals");
        let arr: Vec<i64> = c["arrived_at"].as_array().unwrap().iter().map(|x| x.as_i64().unwrap()).collect();
        assert_eq!(arr.len(), MAX_ITEMS_PER_DAY);
        m.arrived_at.copy_from_slice(&arr);
        let (now, e, kd) = (i(c, "now"), n(c, "e"), c["kd"].as_bool().unwrap());
        let (lo, hi) = m.floor_bounds(now).unwrap();
        let got = json!({ "fresh": m.fresh(now), "bounds": [lo, hi], "item_cap": m.item_cap(now, kd).unwrap(),
            "max_item_cost": m.max_item_cost(now, e, kd).unwrap(), "net_units": m.net_units(e), "arrival_room": m.arrival_room(now) });
        assert_eq!(&got, &c["out"], "case {k}: {c}");
        nontrivial += (c["out"]["max_item_cost"].as_u64().unwrap() > 0) as usize;
    }
    assert!(nontrivial >= 20, "the vectors reach the advance's cap: {nontrivial}");
    let hx = |s: &Value| -> [u8; 32] { hex::decode(s.as_str().unwrap()).unwrap().try_into().unwrap() };
    let root = hx(&v["root"]);
    for l in v["leaves"].as_array().unwrap() {
        let id = l["id"].as_str().unwrap();
        assert_eq!(leaf_of(id), hx(&l["leaf"]), "{id}");
        let proof: Vec<[u8; 32]> = l["proof"].as_array().unwrap().iter().map(hx).collect();
        assert_eq!(verify_proof(&proof, &root, hx(&l["leaf"])), l["verifies"].as_bool().unwrap(), "{id}");
    }
    for s in v["sources"].as_array().unwrap() {
        let vout = s["vout"].as_u64().unwrap() as u32;
        assert_eq!(keccak(&[&hx(&s["tx"]), &vout.to_be_bytes()]), hx(&s["source"]));
    }
    for t in v["taproot"].as_array().unwrap() {
        assert_eq!(is_taproot_on(t["address"].as_str().unwrap(), "bc"), t["taproot"].as_bool().unwrap(), "{t}");
    }
    for t in v["taproot_tb"].as_array().unwrap() {
        assert_eq!(is_taproot_on(t["address"].as_str().unwrap(), "tb"), t["taproot"].as_bool().unwrap(), "{t}");
    }
}

// New: the books survive stable memory byte for byte (every map, ticket, raffle and the treasury), and unknown bytes are refused.
#[test]
fn the_books_round_trip_through_their_versioned_stable_encoding() {
    let mut env = Env::new();
    env.add_collection(1, value_params(FLOOR, 5, 2, REVENUE_TARGET).unwrap());
    env.use_listing(0);
    ok(env.post(FLOOR));
    env.seed_units(HOLDER, 600 * SOL);
    ok(env.wrap_nft(1, tx_hash(1), MintTo::Holder(USER)));
    ok(env.wrap_nft(2, tx_hash(2), MintTo::Module));
    ok(env.redeem(USER, Destination::Eth([0x42; 20])));
    ok(env.resolve(0));
    ok(env.b.init_raffle(0, [9; 32]));
    env.top_up(3 * FLOOR);
    ok(env.fund_prize());
    ok(env.b.treasury.set_ops([8; 32], env.now));
    env.fund_round(30 * SOL);
    ok(env.distribute(0));
    let bytes = encode(&env.b);
    let back = ok(decode(&bytes));
    assert_eq!(back, env.b);
    assert_eq!(BOOKS_VERSION, 1);
    expect_err(decode(&bytes[..bytes.len() - 3]), BooksError::BadVersion);
    expect_err(decode(b"not candid"), BooksError::BadVersion);
    expect_err(decode(&candid::encode_one(7u32).unwrap()), BooksError::BadVersion);
    println!("the books of 2 collections, 2 items, 1 ticket, a raffle: {} bytes", bytes.len());
}
